import java.util.Scanner;

public class Main {
    static final int maxn = 505;
    static int n, m, mod;
    static int[][] C = new int[maxn][maxn];
    static int[] f = new int[maxn], g = new int[maxn];
    static int[][] F = new int[maxn][maxn], G = new int[maxn][maxn];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();

        for (int i = 0; i <= n; ++i) {
            C[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
            }
        }

        f[0] = 1;
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= i; ++j) {
                long temp1 = (long)f[j - 1] * f[i - j] % mod;
                temp1 = temp1 * (i + 1) % mod;
                temp1 = temp1 * C[i - 1][j - 1] % mod;
                f[i] = (int)((f[i] + temp1) % mod);

                long temp2 = (long)f[j - 1] * g[i - j] % mod;
                temp2 = temp2 * (i + 1) % mod;
                temp2 = temp2 * C[i - 1][j - 1] % mod;
                g[i] = (int)((g[i] + temp2) % mod);

                long temp3 = (long)g[j - 1] * f[i - j] % mod;
                temp3 = temp3 * (i + 1) % mod;
                temp3 = temp3 * C[i - 1][j - 1] % mod;
                g[i] = (int)((g[i] + temp3) % mod);

                int sumC = (C[j][2] + C[i - j + 1][2]) % mod;
                long temp4 = (long)f[j - 1] * f[i - j] % mod;
                temp4 = temp4 * sumC % mod;
                temp4 = temp4 * C[i - 1][j - 1] % mod;
                g[i] = (int)((g[i] + temp4) % mod);
            }
        }

        F[0][0] = 1;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j <= Math.min(i, m); ++j) {
                for (int l = 0; l < j; ++l) {
                    long tempF = (long)f[l] * F[i - l - 1][j - l] % mod;
                    tempF = tempF * C[j][l] % mod;
                    F[i][j] = (int)((F[i][j] + tempF) % mod);

                    long tempG1 = (long)g[l] * F[i - l - 1][j - l] % mod;
                    tempG1 = tempG1 * C[j][l] % mod;
                    G[i][j] = (int)((G[i][j] + tempG1) % mod);

                    long tempG2 = (long)f[l] * G[i - l - 1][j - l] % mod;
                    tempG2 = tempG2 * C[j][l] % mod;
                    G[i][j] = (int)((G[i][j] + tempG2) % mod);
                }
                F[i][j] = (F[i][j] + f[j]) % mod;
                G[i][j] = (G[i][j] + g[j]) % mod;
            }
        }

        System.out.println(G[n][m]);
        sc.close();
    }
}

